-- Phase 7 research run record (D-18, RSRCH-06, DIAG-05, ADR-09). Generated by
-- `pnpm exec drizzle-kit generate --name research_job_runs` on top of the merged
-- journal (position 0010, after 0009_codex_activity, per 07-RECONCILE.md R-MIG),
-- then hand-edited as 0003 and 0007 were:
--   1. The nine `ALTER TABLE job_runs ADD` statements are plain, with no
--      `IF NOT EXISTS`: SQLite has no ADD COLUMN IF NOT EXISTS. They are safe
--      because `applyMigrations` runs this file exactly once, in one transaction
--      with the schema_version bump, so a store has all of them or none (the 0003
--      header says the same). Every added column is nullable, so rows written
--      before this file read null. `run_trigger` is not named `trigger`, an SQL
--      keyword.
--   2. The partial unique index at the end was written by hand. drizzle-kit does
--      not generate partial indexes, so the generated snapshot does not know it
--      (the 0007 triggers are the precedent). It allows at most one queued,
--      starting or running job run per job key; it is the crash-safe backstop for
--      the select-first check in `startJobRun`, and `recoverInterruptedRuns` moves
--      an interrupted run to stale so a crash can never leave it blocking.
--      `IF NOT EXISTS` was added to it.
--
-- REBUILD HAZARD. A LATER migration that makes drizzle-kit rebuild `job_runs`
-- (a `__new_` table, a copy, DROP TABLE, RENAME) silently drops the index above.
-- Its author MUST recreate `job_runs_one_inflight_per_job` in that same
-- migration; `migration-research.audit.test.ts` applies every migration to a
-- fresh database and asserts the index exists and still refuses a second
-- in-flight row.
--
-- The new columns hold run ids, note ids, source ids, closed codes, counts and ISO
-- instants ONLY. No fetched text, title, URL, model output or remote error string
-- column exists and none may be added (research Pitfall 8); the audit test walks
-- the column names and the stored JSON.
--
-- Applied files are never renumbered, renamed or edited (ADR-0018, M-1).
ALTER TABLE `job_runs` ADD `ended_at` text;--> statement-breakpoint
ALTER TABLE `job_runs` ADD `outcome` text;--> statement-breakpoint
ALTER TABLE `job_runs` ADD `unavailable_sources` text;--> statement-breakpoint
ALTER TABLE `job_runs` ADD `report_note_id` text;--> statement-breakpoint
ALTER TABLE `job_runs` ADD `error_code` text;--> statement-breakpoint
ALTER TABLE `job_runs` ADD `stage_log` text;--> statement-breakpoint
ALTER TABLE `job_runs` ADD `source_count` integer;--> statement-breakpoint
ALTER TABLE `job_runs` ADD `source_total` integer;--> statement-breakpoint
ALTER TABLE `job_runs` ADD `run_trigger` text;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS `job_runs_one_inflight_per_job` ON `job_runs` (`job_key`) WHERE `state` IN ('queued', 'starting', 'running');
